 "content": "def transform(grid):
    """Propagate each marker to repeated locations with the same local foreground motif."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    fg = [[v != 0 for v in row] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 1)]

    def bit(r, c):
        return 0 <= r < h and 0 <= c < w and fg[r][c]

    for sr, sc, color in markers:
        # The marker identifies a local motif. Match it throughout the canvas;
        # overlapping matches naturally create larger colored patches.
        radius = 2
        templ = [[bit(sr + dr, sc + dc) for dc in range(-radius, radius + 1)]
                 for dr in range(-radius, radius + 1)]
        found = []
        for r in range(h):
            for c in range(w):
                if not fg[r][c]:
                    continue
                if all(bit(r + dr, c + dc) == templ[dr + radius][dc + radius]
                       for dr in range(-radius, radius + 1)
                       for dc in range(-radius, radius + 1)):
                    found.append((r, c))
        # If the larger motif is unique, use its immediate neighborhood as a
        # fallback; this accommodates small motifs near an edge.
        if len(found) <= 1:
            radius = 1
            templ = [[bit(sr + dr, sc + dc) for dc in range(-radius, radius + 1)]
                     for dr in range(-radius, radius + 1)]
            found = []
            for r in range(h):
                for c in range(w):
                    if fg[r][c] and all(bit(r + dr, c + dc) == templ[dr + radius][dc + radius]
                                        for dr in range(-radius, radius + 1)
                                        for dc in range(-radius, radius + 1)):
                        found.append((r, c))
        for r, c in found:
            if grid[r][c] == 1 or (r, c) == (sr, sc):
                out[r][c] = color
    return out
